<template><div class="app-container"><div class="filter-container"><el-select v-model="query.flowType" clearable placeholder="流水类型" class="filter-item"><el-option v-for="item in flowTypeOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-input v-model="query.requestNo" clearable placeholder="请求号" class="filter-item request-filter" /><el-button type="primary" @click="load">查询</el-button></div><el-table v-loading="loading" :data="list" border><el-table-column prop="flowNo" label="流水号" min-width="170" /><el-table-column label="资金账户" min-width="180"><template slot-scope="{row}"><div>{{ row.applicantName || '用户不存在' }}</div><div class="sub-text">{{ row.roleName || '身份未配置' }} / {{ row.regionName || '区域未配置' }}</div></template></el-table-column><el-table-column label="流水类型" width="170"><template slot-scope="{row}"><el-tag size="mini" :type="row.statusTag || 'info'">{{ row.fundFlowTypeText || row.flowTypeText || '未配置' }}</el-tag></template></el-table-column><el-table-column prop="changeAmount" label="变动金额" width="115" /><el-table-column prop="beforeAmount" label="变动前" width="110" /><el-table-column prop="afterAmount" label="变动后" width="110" /><el-table-column label="业务来源" width="140"><template slot-scope="{row}">{{ row.sourceTypeText || '未配置' }}</template></el-table-column><el-table-column prop="requestNo" label="请求号" min-width="160" /><el-table-column prop="remark" label="备注" min-width="170" /><el-table-column prop="createTime" label="时间" width="165" /></el-table></div></template>
<script>import { getJkFundFlowList } from '@/api/jkBusiness'; import { jkFundFlowTypeOptions } from '@/utils/jk-display'; export default { data() { return { flowTypeOptions: jkFundFlowTypeOptions, query: { flowType: '', requestNo: '' }, list: [], loading: false } }, created() { this.load() }, methods: { load() { this.loading = true; getJkFundFlowList(this.query).then(response => { this.list = response.data || response || [] }).finally(() => { this.loading = false }) } }}; </script>
<style scoped>.filter-item{width:170px;margin-right:8px}.request-filter{width:180px}.sub-text{font-size:12px;color:#909399}</style>
